theorem readLength_none_of_takeBytes_leading_zero {bs rest tail : List Byte}
    {b : Byte} {n : Nat}
    (h : takeBytes bs n = some ((0 : Byte) :: b :: tail, rest)) :
    readLength bs n = none

theorem readLength_none_of_takeBytes_none {bs : List Byte} {n : Nat}
    (h : takeBytes bs n = none) :
    readLength bs n = none

theorem readLength_some_of_takeBytes_nil {bs rest : List Byte} {n : Nat}
    (h : takeBytes bs n = some ([], rest)) :
    readLength bs n = some (0, rest)

theorem readLength_some_of_takeBytes_nonzero {bs rest tail : List Byte}
    {b : Byte} {n : Nat}
    (h : takeBytes bs n = some (b :: tail, rest))
    (hne : b ≠ (0 : Byte)) :
    readLength bs n = some (Nat.fromBytesBE (b :: tail), rest)

theorem readLength_some_of_takeBytes_single {bs rest : List Byte}
    {b : Byte} {n : Nat}
    (h : takeBytes bs n = some ([b], rest)) :
    readLength bs n = some (b.toNat, rest)

theorem Nat.length_le_of_canonical_lt {bs : List Byte} {k : Nat}
    (hcanon : bs.headD 1 ≠ 0) (hlt : Nat.fromBytesBE bs < 256 ^ k) :
    bs.length ≤ k

theorem encode_append_cancel {i₁ i₂ : RLPItem} {r₁ r₂ : List Byte}
    (h₁ : (encode i₁).length < 256 ^ 8) (h₂ : (encode i₂).length < 256 ^ 8)
    (heq : encode i₁ ++ r₁ = encode i₂ ++ r₂) : i₁ = i₂ ∧ r₁ = r₂

theorem encode_prefix_unambiguous {i₁ i₂ : RLPItem}
    (h₁ : (encode i₁).length < 256 ^ 8) (h₂ : (encode i₂).length < 256 ^ 8)
    (hpre : encode i₁ <+: encode i₂) : i₁ = i₂

theorem decode_injective {bs₁ bs₂ : List Byte} {item : RLPItem}
    (h₁ : decode bs₁ = some (item, [])) (h₂ : decode bs₂ = some (item, [])) :
    bs₁ = bs₂

theorem encode_decodeItems {n : Nat} {bs : List Byte} {items : List RLPItem}
    {rest : List Byte} (h : decodeItems n bs = some (items, rest)) :
    encode.encodeItems items ++ rest = bs

theorem decodeAux_all_fuel_of_decode_ge {n : Nat} {bs : List Byte}
    {r : RLPItem × List Byte} (h : decodeAux n bs = some r) :
    ∀ m, n ≤ m + 1 → decodeAux (m + 1) bs = some r

theorem decodeItems_mono_fuel {n m : Nat} {bs : List Byte}
    {r : List RLPItem × List Byte}
    (hle : n ≤ m) (h : decodeItems n bs = some r) : decodeItems m bs = some r

theorem decode_span_longBytes {pfx : Byte} {rest0 : List Byte} {item : RLPItem}
    {rest : List Byte} {lenVal : Nat} {lenRest : List Byte}
    (h : decode (pfx :: rest0) = some (item, rest))
    (hlo : 0xB8 ≤ pfx.toNat) (hhi : pfx.toNat ≤ 0xBF)
    (hread : readLength rest0 (rlpPrefixLongBytesLenOfLen pfx) = some (lenVal, lenRest)) :
    (encode item).length = 1 + rlpPrefixLongBytesLenOfLen pfx + lenVal

theorem decode_span_longList {pfx : Byte} {rest0 : List Byte} {item : RLPItem}
    {rest : List Byte} {lenVal : Nat} {lenRest : List Byte}
    (h : decode (pfx :: rest0) = some (item, rest))
    (hlo : 0xF8 ≤ pfx.toNat)
    (hread : readLength rest0 (rlpPrefixLongListLenOfLen pfx) = some (lenVal, lenRest)) :
    (encode item).length = 1 + rlpPrefixLongListLenOfLen pfx + lenVal

theorem decodeScalar_eq_some_imp {bs rest : List Byte} {n : Nat}
    (h : decodeScalar bs = some (n, rest)) :
    ∃ data, bs = encodeBytes data ++ rest ∧ Nat.fromBytesBE data = n

theorem byte_of_ge {code : List (BitVec 8)} {idx : Nat}
    (h : code.length ≤ idx) :
    byte code idx = 0

theorem byte_of_lt {code : List (BitVec 8)} {idx : Nat}
    (h : idx < code.length) :
    byte code idx = code[idx]

theorem byte_of_ge {data : List (BitVec 8)} {idx : Nat}
    (h : data.length ≤ idx) :
    byte data idx = 0

theorem byte_of_lt {data : List (BitVec 8)} {idx : Nat}
    (h : idx < data.length) :
    byte data idx = data[idx]

theorem mem_validJumpDestinations (code : List Byte) {idx : Nat}
    (h : idx ∈ validJumpDestinations code) :
    idx < code.length ∧ (code.getD idx 0).toNat = 0x5b

theorem validJDaux_mem (code : List Byte) (fuel pc : Nat) {idx : Nat}
    (h : idx ∈ validJDaux code fuel pc) :
    idx < code.length ∧ (code.getD idx 0).toNat = 0x5b
